#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

banner "OceanViewFlats · SEO & GEO Search Engine + Entity Setup"

# ── Stage 1: Live Production Redirect & AI Crawler Verification ───────────
stage "Verify live 301 redirects, robots.txt, llms.txt & AI crawler reachability"
say "Before submitting sitemaps, let's verify that production serves canonical 301s"
say "and does not block AI search crawlers at the cPanel/ModSecurity/WAF layer."

if command -v curl >/dev/null 2>&1; then
  check_status() {
    local label="$1" url="$2" ua="${3:-Mozilla/5.0}" expected="$4"
    local code
    code=$(curl -sS -o /dev/null -w '%{http_code}' -A "$ua" --max-time 10 "$url" || echo "ERR")
    if [[ "$code" == "$expected" ]]; then
      printf '  %s✓%s %s → HTTP %s\n' "$GREEN" "$RESET" "$label" "$code"
    else
      warn "$label → HTTP $code (expected $expected)"
    fi
  }

  check_status "Apex → www redirect" "https://oceanviewflats.com/" "Mozilla/5.0" "301"
  check_status "/index.html → / redirect" "https://www.oceanviewflats.com/index.html" "Mozilla/5.0" "301"
  check_status "Canonical root" "https://www.oceanviewflats.com/" "Mozilla/5.0" "200"
  check_status "robots.txt" "https://www.oceanviewflats.com/robots.txt" "Mozilla/5.0" "200"
  check_status "sitemap.xml" "https://www.oceanviewflats.com/sitemap.xml" "Mozilla/5.0" "200"
  check_status "llms.txt (OAI-SearchBot)" "https://www.oceanviewflats.com/llms.txt" "OAI-SearchBot/1.0" "200"
  check_status "llms.txt (ClaudeBot)" "https://www.oceanviewflats.com/llms.txt" "ClaudeBot/1.0" "200"
  check_status "llms.txt (PerplexityBot)" "https://www.oceanviewflats.com/llms.txt" "PerplexityBot/1.0" "200"
  check_status "llms.txt (Applebot-Extended)" "https://www.oceanviewflats.com/llms.txt" "Applebot-Extended/0.1" "200"
else
  warn "curl is not installed; skipping automated HTTP checks."
fi
note "If any AI crawler returned 403, allowlist those user-agents in cPanel/WAF before proceeding."
pause "Press Enter once live checks look good"

# ── Stage 2: Google Search Console & Rich Results ─────────────────────────
stage "Google Search Console: Domain property, sitemap & Rich Results"
say "Consolidate search equity on https://www.oceanviewflats.com/ and trigger recrawl."
open_url "https://search.google.com/search-console"
step "Verify a Domain property (oceanviewflats.com via DNS TXT) if you only have a URL-prefix property."
step "Open Sitemaps → submit: https://www.oceanviewflats.com/sitemap.xml"
step "Inspect & click 'Request Indexing' on:"
note "  - https://www.oceanviewflats.com/"
note "  - https://www.oceanviewflats.com/Oceanview1707/"
note "  - https://www.oceanviewflats.com/Oceanview1606/"
note "  - https://www.oceanviewflats.com/contact/"
note "  - https://www.oceanviewflats.com/es.html"
if confirm "Open Google Rich Results Test now to validate Property 1707 JSON-LD?"; then
  open_url "https://search.google.com/test/rich-results?url=https%3A%2F%2Fwww.oceanviewflats.com%2FOceanview1707%2F"
fi
pause "Press Enter when Google Search Console updates are done"

# ── Stage 3: Bing Webmaster Tools (Feeds ChatGPT Search & Copilot) ────────
stage "Bing Webmaster Tools: GSC import & sitemap"
say "ChatGPT Search (OAI-SearchBot) and Microsoft Copilot rely heavily on Bing's index."
open_url "https://www.bing.com/webmasters"
step "Sign in → click 'Import your sites from Google Search Console' (fastest verification)."
step "Select https://www.oceanviewflats.com/ and confirm import."
step "Open Sitemaps → verify or submit: https://www.oceanviewflats.com/sitemap.xml"
pause "Press Enter when Bing Webmaster Tools is connected"

# ── Stage 4: IndexNow Key & GitHub Repository Variable ────────────────────
stage "IndexNow: Generate public key & configure GitHub Actions variable"
say "IndexNow pushes URL updates directly to Bing/Yandex/Seznam/Naver after every SFTP deploy."
note "By protocol, IndexNow keys are public (served at https://www.oceanviewflats.com/<key>.txt)."
note "We store INDEXNOW_KEY in GitHub Repository Variables (vars.INDEXNOW_KEY) for issue #315."

SUGGESTED_INDEXNOW_KEY=""
if command -v openssl >/dev/null 2>&1; then
  SUGGESTED_INDEXNOW_KEY=$(openssl rand -hex 16)
elif command -v uuidgen >/dev/null 2>&1; then
  SUGGESTED_INDEXNOW_KEY=$(uuidgen | tr -d '-' | tr '[:upper:]' '[:lower:]')
fi
if [[ -n "$SUGGESTED_INDEXNOW_KEY" ]]; then
  say "Suggested 32-char hex key: ${BOLD}${SUGGESTED_INDEXNOW_KEY}${RESET}"
fi
ask INDEXNOW_KEY "Paste an IndexNow key (or paste the suggested key above; blank to skip):"
if [[ -n "$INDEXNOW_KEY" ]]; then
  if [[ "$INDEXNOW_KEY" =~ ^[A-Za-z0-9-]{8,128}$ ]]; then
    write_env INDEXNOW_KEY "$INDEXNOW_KEY"
    set_var INDEXNOW_KEY "$INDEXNOW_KEY"
  else
    warn "Invalid IndexNow key format (must be 8-128 alphanumeric/hyphen chars); skipping."
    SKIPPED+=("GitHub variable INDEXNOW_KEY (invalid format)")
  fi
else
  SKIPPED+=("GitHub variable INDEXNOW_KEY (skipped by user)")
fi
pause "Press Enter to continue to local entity profiles"

# ── Stage 5: Google Business Profile ──────────────────────────────────────
stage "Google Business Profile: Canonical NAP, RNT & direct website link"
say "Claim or verify OceanViewFlats on Google Business Profile for Maps + AI entity trust."
open_url "https://business.google.com/"
step "Use exact canonical NAP matching JSON-LD:"
note "  Name:     OceanViewFlats Santa Marta"
note "  Address:  Edificio Salguero Sunset, Calle 26 # 2-80, Playa Salguero,"
note "            Santa Marta, Magdalena 470006, Colombia"
note "  Phone:    +57 310 815-5234"
note "  Website:  https://www.oceanviewflats.com/"
note "  Hours:    Check-in 15:00 / Check-out 11:00"
note "  Licenses: RNT #268781 (1707) & RNT #270413 (1606)"
step "Once created/verified, copy your public Google Maps / Business Profile URL."
ask GBP_PROFILE_URL "Paste your Google Business Profile URL (or Enter to skip for now):"
if [[ -n "$GBP_PROFILE_URL" ]]; then
  write_env GBP_PROFILE_URL "$GBP_PROFILE_URL"
fi
pause "Press Enter to continue"

# ── Stage 6: Apple Business Connect & Social Profiles (sameAs) ────────────
stage "Apple Business Connect & optional social profiles (sameAs)"
say "Apple Business Connect feeds Apple Maps, Siri, and Apple Intelligence."
open_url "https://businessconnect.apple.com/"
step "Add OceanViewFlats Santa Marta at Edificio Salguero Sunset with identical NAP + website."
ask APPLE_BUSINESS_CONNECT_URL "Paste Apple Maps / Business Connect URL (or Enter to skip):"
if [[ -n "$APPLE_BUSINESS_CONNECT_URL" ]]; then
  write_env APPLE_BUSINESS_CONNECT_URL "$APPLE_BUSINESS_CONNECT_URL"
fi
ask INSTAGRAM_URL "Paste official Instagram URL if active (or Enter to skip):"
if [[ -n "$INSTAGRAM_URL" ]]; then
  write_env INSTAGRAM_URL "$INSTAGRAM_URL"
fi
ask TRIPADVISOR_URL "Paste official TripAdvisor URL if active (or Enter to skip):"
if [[ -n "$TRIPADVISOR_URL" ]]; then
  write_env TRIPADVISOR_URL "$TRIPADVISOR_URL"
fi
note "Once issue #313 lands, add any verified URLs above into EXTERNAL_ENTITY_URLS in src/constants/config.ts."

finish
}

run_wizard "$@"; exit
